const PREFIX='soundcut-shell-'+new URL(self.registration.scope).pathname;
const CACHE=PREFIX+'v2.0.0';
const ASSETS=['./','./index.html','./style.css','./editor-v2.css','./audio.js','./editor-core.js','./app.js','./converter.js','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest',...['classes','const','errors','index','types','utils','worker'].map(f=>`./vendor/ffmpeg/${f}.js`)];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith(PREFIX)&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;if(!ASSETS.some(asset=>new URL(asset,self.registration.scope).pathname===url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&!response.redirected){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(event.request,copy)));}return response;}).catch(async()=>{const cached=await caches.match(event.request);return cached||new Response('请连接网络完成首次载入。',{status:503});}));});
